#include <stdio.h>
// 链式查询：授权信号(BG)沿物理链传递，第一个有请求的设备截获 -> 链前永远优先
// req[c] 的 bit i = 第 c 拍设备 i 是否请求总线（4 个设备，设备0链前=最高优先级）
int req[8] = {1, 6, 8, 2, 13, 0, 4, 6};
int main() {
    printf("链式查询仲裁 (优先级: 设备0 > 1 > 2 > 3, 链前优先)\n");
    printf("cycle   请求(mask)   授权设备\n");
    for (int c = 0; c < 8; c++) {
        int r = req[c];
        int g = -1;
        for (int i = 0; i < 4; i++) {
            if (r & (1 << i)) { g = i; break; }
        }
        printf("  %d       %2d           %d\n", c, r, g);
    }
    return 0;
}
